import { test } from 'node:test';
import assert from 'node:assert/strict';
import { clamp } from '../src/clamp.ts';
import { clamp as clampFromIndex } from '../src/index.ts';

test('keeps a value inside the range', () => {
  assert.equal(clamp(5, 0, 10), 5);
  assert.equal(clamp(0, 0, 10), 0);
  assert.equal(clamp(10, 0, 10), 10);
});

test('raises a value below the minimum', () => {
  assert.equal(clamp(-3, 0, 10), 0);
  assert.equal(clamp(0.5, 1, 2), 1);
});

test('lowers a value above the maximum', () => {
  assert.equal(clamp(42, 0, 10), 10);
  assert.equal(clamp(1.5, 0, 1), 1);
});

test('is re-exported from the barrel', () => {
  assert.equal(clampFromIndex, clamp);
});

